const fn = new Function(code + "\nreturn { withRetry };");
const { withRetry } = fn();
let calls = 0;
const out = withRetry(() => { calls++; return "done"; }, 3);
if (out !== "done") throw new Error("The successful result must be returned.");
if (calls !== 1) throw new Error("A task that succeeds first try must be called exactly once.");

const fn = new Function(code + "\nreturn { withRetry };");
const { withRetry } = fn();
let calls = 0;
const out = withRetry(() => { calls++; if (calls < 3) throw new Error("flaky"); return "ok"; }, 3);
if (out !== "ok") throw new Error("A task that fails twice then succeeds should return 'ok'.");
if (calls !== 3) throw new Error("The task should have been attempted 3 times (2 failures + 1 success).");

const fn = new Function(code + "\nreturn { withRetry };");
const { withRetry } = fn();
let calls = 0;
let err;
try {
  withRetry(() => { calls++; throw new Error("attempt " + calls); }, 2);
} catch (e) { err = e; }
if (!err) throw new Error("An always-failing task must eventually throw.");
if (calls !== 3) throw new Error("Initial call + 2 retries = 3 attempts.");
if (err.message !== "attempt 3") throw new Error("The rethrown error must be the LAST one (attempt 3), not the first.");
